ruleset:
add table ip sbxw_egress
delete table ip sbxw_egress
add table ip6 sbxw_egress
delete table ip6 sbxw_egress
table ip sbxw_egress {
  chain output {
    type filter hook output priority 0; policy drop;
    oif "lo" accept
    ct state established,related accept
    ip daddr 169.254.169.254/32 counter drop comment "metadata"
    ip daddr 169.254.0.0/16 counter drop comment "link-local"
    ip daddr 10.0.0.0/8 counter drop comment "private"
    ip daddr 172.16.0.0/12 counter drop comment "private"
    ip daddr 192.168.0.0/16 counter drop comment "private"
    ip daddr 100.64.0.0/10 counter drop comment "cgnat"
    ip daddr 0.0.0.0/8 counter drop comment "this-network"
    ip daddr 224.0.0.0/4 counter drop comment "multicast"
    ip daddr 240.0.0.0/4 counter drop comment "reserved"
    ip daddr 1.1.1.1 tcp dport 443 accept comment "allow"
    counter drop comment "default"
  }
}
table ip6 sbxw_egress {
  chain output {
    type filter hook output priority 0; policy drop;
    oif "lo" accept
    ct state established,related accept
    ip6 daddr fe80::/10 counter drop comment "ipv6-link-local"
    counter drop comment "ipv6"
  }
}

